$f=$GLOBALS['cli_fixture'];
$slugs=array_flip($f['posts']??array());
foreach($f['content_before'] as $id=>$before) {
    $slug=$slugs[$id]??'';
    $actual=get_post($id,ARRAY_A); $expected=$before['post'];
    // Derived taxonomy fields are checked independently below.
    unset($actual['post_category'],$actual['tags_input'],$expected['post_category'],$expected['tags_input']);
    if(in_array($slug,array(),true)) {
        if(in_array('delete',array(),true)) { if($actual!==null) { return false; } continue; }
        foreach(array() as $key) { unset($actual[$key],$expected[$key]); }
    }
    if($actual!==$expected) { return false; }
    $meta=get_post_meta($id); $wanted=$before['meta'];
    if(in_array($slug,array(),true)) {
        foreach(array_unique(array_merge(array_keys($meta),array_keys($wanted))) as $key) {
            foreach(array() as $allowed) {
                if($key===$allowed || (str_starts_with($allowed,'prefix:') && str_starts_with($key,substr($allowed,7)))) { unset($meta[$key],$wanted[$key]); }
            }
        }
    }
    if($meta!==$wanted) { return false; }
    $cats=wp_get_post_categories($id); $tags=wp_get_post_tags($id,array('fields'=>'ids'));
    sort($cats); sort($tags); sort($before['category']); sort($before['tags']);
    if(!in_array($slug,array(),true) && $cats!==$before['category']) { return false; }
    if(!in_array($slug,array(),true) && $tags!==$before['tags']) { return false; }
} return true;

